var t=`1133-philly-cheesesteak`;var n=`world-1133`;var s=`US`;var l=`northern-america`;var a=4;var o=20;var r={en:`Philly Cheesesteak`,ua:`Філадельфійський чізстейк`};var d={en:`Philly Cheesesteak is a dish from United States prepared with beef ribeye, yellow onion, green bell pepper, bread roll. This is a home-scale version with measured ingredients in the individual steps where they are used. Ordinary bread rolls replace long Philly-style hoagie rolls.`,ua:`Філадельфійський чізстейк, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: яловичий рібай, жовта цибуля, зелений солодкий перець, булочка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Звичайні булочки замінюють довгі філадельфійські роли.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`beef-ribeye`,700,`g`],[`yellow-onion`,230,`g`],[`canola-oil`,40,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 4 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 4 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:4,i:[[`green-bell-pepper`,180,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`bread-roll`,4,`pcs`],[`provolone`,220,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]}];var g={slug:t,id:n,country:`US`,region:l,servings:4,minutes:20,title:r,text:d,steps:h};export{s as country,g as default,n as id,o as minutes,l as region,a as servings,t as slug,h as steps,d as text,r as title};